# Icons offered in the admin icon picker (content icons only)
ICON_NAMES = [
    "code", "terminal", "server", "database", "layers", "layout", "workflow", "cpu",
    "smartphone", "wrench", "puzzle", "git", "globe", "palette", "lightbulb", "rocket",
    "shield", "chart", "briefcase", "graduation", "award", "book", "star", "target",
]


def icon(name: str, size: int = 20, cls: str = "") -> Markup:
    if name in _FILLED:
        body, attrs = _FILLED[name], 'fill="currentColor"'
    else:
        body = _STROKE.get(name, _STROKE["code"])
        attrs = 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"'
    klass = f"icon {cls}".strip()
    return Markup(
        f'<svg class="{klass}" width="{size}" height="{size}" viewBox="0 0 24 24" {attrs} aria-hidden="true" focusable="false">{body}</svg>'
    )
